import{_ as e,o as s,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"インデックス管理","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/index-drives.md","filePath":"ja-JP/user-guide/settings/index-drives.md","lastUpdated":1787586465000}'),l={name:"ja-JP/user-guide/settings/index-drives.md"};function n(i,o,a,d,g,c){return s(),r("div",null,[...o[0]||(o[0]=[t('<h1 id="インデックス管理" tabindex="-1">インデックス管理 <a class="header-anchor" href="#インデックス管理" aria-label="Permalink to &quot;インデックス管理&quot;">​</a></h1><p>インデックス設定画面では、ローカルドライブ、ネットワーク共有、WSL、個別フォルダーに対するインデックス作成範囲、更新スケジュール、および除外ルールを細かく制御します。画面上部には <strong>ローカルドライブ</strong>、<strong>ネットワークドライブ</strong>、<strong>WSL</strong>（該当環境検出時のみ）、<strong>フォルダー</strong>、<strong>除外ルール</strong> の 5 つのタブが配置されています。</p><h2 id="_1-ローカルドライブ-local-drives" tabindex="-1">1. ローカルドライブ（Local Drives） <a class="header-anchor" href="#_1-ローカルドライブ-local-drives" aria-label="Permalink to &quot;1. ローカルドライブ（Local Drives）&quot;">​</a></h2><ul><li><strong>ステータスサマリー</strong>：現在インデックス化されている物理ドライブ数と総アイテム数が表示され、全ドライブの一括再構築を行う <strong>インデックス再構築</strong> ボタンが配置されています。</li><li><strong>ドライブ一覧行</strong>： <ul><li><strong>有効/無効チェックボックス</strong>：パーティションごとにインデックス作成を個別に切り替え。</li><li><strong>ファイルシステムと状態</strong>：ファイルシステムの種類（NTFS、ReFS、FAT32、exFAT 等）、稼働状態、インデックス済みアイテム数を表示。</li><li><strong>個別ドライブ操作</strong>：<strong>再構築</strong> と <strong>削除</strong> ボタン。スキャン実行中は動的に <strong>停止</strong> ボタンが表示されます。</li></ul></li><li><strong>リアルタイム監視</strong>：NTFS / ReFS は Windows の USN 変更ジャーナルを読み取ってミリ秒単位で同期し、FAT32 / exFAT はファイル変更イベントを監視します。</li><li><strong>無停止での再構築</strong>：ドライブの再構築中も、新規インデックスが完成するまでは既存のインデックスが検索に応答し続けるため、検索が途切れることはありません。再起動等で中断されても次回起動時に続きから再開されます。</li></ul><h2 id="_2-ネットワークドライブ-network-drives" tabindex="-1">2. ネットワークドライブ（Network Drives） <a class="header-anchor" href="#_2-ネットワークドライブ-network-drives" aria-label="Permalink to &quot;2. ネットワークドライブ（Network Drives）&quot;">​</a></h2><ul><li><strong>ネットワーク共有の対応</strong>：マウント済みの Windows ネットワークドライブ（SMB / NAS）を一覧表示。</li><li><strong>更新モード（Refresh Mode）</strong>：ローカルの変更ジャーナルが存在しないため、定期スキャン周期を設定可能： <ul><li><strong>手動</strong> —— 「インデックス再構築」クリック時のみスキャン。</li><li><strong>15 分ごと</strong> —— 頻繁に更新される共有向け。</li><li><strong>1 時間ごと</strong> —— 標準的な定期更新。</li><li><strong>毎日</strong> —— アーカイブ用ストレージ向け。</li></ul></li><li><strong>シンボリックリンク循環保護</strong>：NAS 上の循環シンボリックリンクやジャンクションによる無限ループを防ぐため、ループ検知エンジンが重複パスを自動スキップします。</li></ul><h2 id="_3-wsl-linux-用-windows-サブシステム" tabindex="-1">3. WSL（Linux 用 Windows サブシステム） <a class="header-anchor" href="#_3-wsl-linux-用-windows-サブシステム" aria-label="Permalink to &quot;3. WSL（Linux 用 Windows サブシステム）&quot;">​</a></h2><p>WSL ディストリビューションがインストールされている場合に自動的に表示されます。</p><ul><li><strong>自動検出</strong>：Ubuntu、Debian、Arch などのインストール済みディストリビューションを自動認識。</li><li><strong>状態と更新</strong>：ネットワークドライブと同様のステータス管理と更新モード（手動 / 15 分ごと / 1 時間ごと / 毎日）を提供。</li><li><strong>ゼロ I/O 検索</strong>：WSL ファイルの検索時はメモリインデックスを直接参照し、Linux サブシステムを起動させたり負荷をかけたりしません。</li></ul><h2 id="_4-フォルダー-folders" tabindex="-1">4. フォルダー（Folders） <a class="header-anchor" href="#_4-フォルダー-folders" aria-label="Permalink to &quot;4. フォルダー（Folders）&quot;">​</a></h2><p>ドライブ全体ではなく、特定の作業フォルダーのみを対象にしたい場合に利用します。</p><ul><li><strong>複数選択での追加</strong>：<strong>フォルダーを追加</strong> をクリックしてピッカーを開き、<code>Ctrl</code> または <code>Shift</code> キーを押しながら複数のフォルダーを一括追加可能。</li><li><strong>UNC パスのサポート</strong>：<code>\\\\server\\share\\projects</code> のようなネットワーク UNC パスも直接登録可能。</li><li><strong>個別更新スケジュール</strong>：各フォルダーごとに独立した有効スイッチ、アイテム数、更新モード（手動 / 15 分ごと / 1 時間ごと / 毎日）を設定できます。</li></ul><h2 id="_5-除外ルール-exclusions" tabindex="-1">5. 除外ルール（Exclusions） <a class="header-anchor" href="#_5-除外ルール-exclusions" aria-label="Permalink to &quot;5. 除外ルール（Exclusions）&quot;">​</a></h2><p>ローカル、ネットワーク、フォルダー全体に適用される除外設定で、3 つのサブタブに分かれています。</p><h3 id="パス除外-path-exclusions" tabindex="-1">パス除外（Path Exclusions） <a class="header-anchor" href="#パス除外-path-exclusions" aria-label="Permalink to &quot;パス除外（Path Exclusions）&quot;">​</a></h3><ul><li><strong>完全プレフィックス一致</strong>：<code>D:\\Cache</code> や環境変数（<code>%ProgramData%</code>、<code>%APPDATA%</code>）を指定して除外。</li></ul><h3 id="glob-ルール-glob-rules" tabindex="-1">Glob ルール（Glob Rules） <a class="header-anchor" href="#glob-ルール-glob-rules" aria-label="Permalink to &quot;Glob ルール（Glob Rules）&quot;">​</a></h3><ul><li><strong>ワイルドカード構文</strong>： <ul><li><code>*</code>：フォルダー単一階層内の任意文字（例: <code>*.tmp</code>、<code>*.log</code>）。</li><li><code>**</code>：再帰的なサブディレクトリ一致（例: <code>**/node_modules/**</code>、<code>**/bin/**</code>、<code>**/obj/**</code>）。</li></ul></li></ul><h3 id="正規表現ルール-regex-rules" tabindex="-1">正規表現ルール（Regex Rules） <a class="header-anchor" href="#正規表現ルール-regex-rules" aria-label="Permalink to &quot;正規表現ルール（Regex Rules）&quot;">​</a></h3><ul><li><strong>高度な正規表現一致</strong>：ドットファイル（<code>^\\.</code>）や Office の一時ファイル（<code>~\\$</code>）などを柔軟に除外。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>除外ルールは <strong>個別追加</strong> と <strong>テキストによる一括インポート/エクスポート</strong> の両方に対応しています。<strong>リストからテキストを生成</strong> でルールをエクスポートし、編集後に <strong>リストに適用</strong> をクリックして一括反映できます。</p></div>',21)])])}const x=e(l,[["render",n]]);export{h as __pageData,x as default};
